def check():
    from build_seo import PRACTICES, CITIES
    ps={p[0] for p in PRACTICES}; cs={c[0] for c in CITIES}
    assert set(P)==cs and set(A)==cs, "city keys mismatch"
    for c in cs:
        assert set(P[c])==ps, f"P practices mismatch in {c}"
        assert set(A[c])==ps, f"A practices mismatch in {c}"
    assert set(APH)==ps and set(ACH)==cs
    seen={}
    for d in (P,A):
        for c in d:
            for p,txt in d[c].items():
                assert txt not in seen, f"duplicate paragraph {c}/{p} == {seen.get(txt)}"
                seen[txt]=(c,p)
    return True

if __name__=="__main__":
    print("ok" if check() else "fail")
